      throw new Error(`Unsupported story model: ${config.model}`);
    }

    // Generate YAML frontmatter
    let yaml = '---\n';
    yaml += `title: ${JSON.stringify(config.title)}\n`;
    yaml += `model: ${config.model}\n`;
    yaml += `totalChapters: ${config.totalChapters}\n`;
